     9	/// A SQL engine. This provides low-level CRUD (create, read, update, delete)
    10	/// operations for table rows, a schema catalog for accessing and modifying
    11	/// table schemas, and interactive SQL sessions that execute client SQL
    12	/// statements. All engine access is transactional with snapshot isolation.
    13	pub trait Engine<'a>: Sized {
    14	    /// The engine's transaction type. This provides both row-level CRUD operations and
    15	    /// transactional access to the schema catalog.
    16	    type Transaction: Transaction + 'a;
    17	
    18	    /// Begins a read-write transaction.
    19	    fn begin(&'a self) -> Result<Self::Transaction>;
    20	    /// Begins a read-only transaction.
    21	    fn begin_read_only(&'a self) -> Result<Self::Transaction>;
    22	    /// Begins a read-only transaction as of a historical version.
    23	    fn begin_as_of(&'a self, version: mvcc::Version) -> Result<Self::Transaction>;
    24	
    25	    /// Creates a client session for executing SQL statements.
    26	    fn session(&'a self) -> Session<'a, Self> {
    27	        Session::new(self)
    28	    }
    29	}
    30	
    31	/// A SQL transaction. Executes transactional CRUD operations on table rows.
    32	/// Provides snapshot isolation (see `storage::mvcc` module for details).
    33	///
    34	/// All methods operate on row batches rather than single rows to amortize the
    35	/// cost. With the Raft engine, each call results in a Raft roundtrip, and we'd
    36	/// rather not have to do that for every single row that's modified.
    37	pub trait Transaction: Catalog {
    38	    /// The transaction's internal MVCC state.
    39	    fn state(&self) -> &mvcc::TransactionState;
    40	
    41	    /// Commits the transaction.
    42	    fn commit(self) -> Result<()>;
    43	    /// Rolls back the transaction.
    44	    fn rollback(self) -> Result<()>;
    45	
    46	    /// Deletes table rows by primary key, if they exist.
    47	    fn delete(&self, table: &str, ids: &[Value]) -> Result<()>;
    48	    /// Fetches table rows by primary key, if they exist.
    49	    fn get(&self, table: &str, ids: &[Value]) -> Result<Vec<Row>>;
    50	    /// Inserts new table rows.
    51	    fn insert(&self, table: &str, rows: Vec<Row>) -> Result<()>;
    52	    /// Looks up a set of primary keys by index values. BTreeSet for testing.
    53	    fn lookup_index(&self, table: &str, column: &str, values: &[Value]) -> Result<BTreeSet<Value>>;
    54	    /// Scans a table's rows, optionally applying the given filter.
    55	    fn scan(&self, table: &str, filter: Option<Expression>) -> Result<Rows>;
    56	    /// Updates table rows by primary key. BTreeMap for testing.
    57	    fn update(&self, table: &str, rows: BTreeMap<Value, Row>) -> Result<()>;
    58	}
    59	
    60	/// The catalog stores table schema information. It must be implemented for
    61	/// Transaction, and is thus fully transactional. For simplicity, it only
    62	/// supports creating and dropping tables -- there are no ALTER TABLE schema
    63	/// changes, nor CREATE INDEX.
    64	pub trait Catalog {
    65	    /// Creates a new table. Errors if it already exists.
    66	    fn create_table(&self, table: Table) -> Result<()>;
    67	    /// Drops a table. Errors if it does not exist, unless if_exists is true.
    68	    /// Returns true if the table existed and was deleted.
    69	    fn drop_table(&self, table: &str, if_exists: bool) -> Result<bool>;
    70	    /// Fetches a table schema, or None if it doesn't exist.
    71	    fn get_table(&self, table: &str) -> Result<Option<Table>>;
    72	    /// Returns a list of all table schemas.
    73	    fn list_tables(&self) -> Result<Vec<Table>>;
    74	
    75	    /// Fetches a table schema, or errors if it does not exist.
    76	    fn must_get_table(&self, table: &str) -> Result<Table> {
    77	        self.get_table(table)?.ok_or_else(|| errinput!("table {table} does not exist"))
    78	    }
    79	}
