/// Operator precedence.
type Precedence = u8;

/// Operator associativity.
enum Associativity {
    Left,
    Right,
}

impl Add<Associativity> for Precedence {
    type Output = Self;

    fn add(self, rhs: Associativity) -> Self {
        match rhs {
            Associativity::Left => self,
            Associativity::Right => self + 1,
        }
    }
}

/// Prefix operators.
enum PrefixOperator {
    Minus, // -a
    Not,   // NOT a
    Plus,  // +a
}

impl PrefixOperator {
    /// The operator precedence.
    fn precedence(&self) -> Precedence {
        14 // High precedence for unary operators
    }

    // The operator associativity. Prefix operators are right-associative by
    // definition.
    fn associativity(&self) -> Associativity {
        Associativity::Right
    }

    /// Builds an AST expression for the operator.
    fn into_expression(self, rhs: ast::Expression) -> ast::Expression {
        match self {
            PrefixOperator::Minus => ast::Expression::Operator(ast::Operator::Negate(Box::new(rhs))),
            PrefixOperator::Not => ast::Expression::Operator(ast::Operator::Not(Box::new(rhs))),
            PrefixOperator::Plus => ast::Expression::Operator(ast::Operator::Identity(Box::new(rhs))),
        }
    }
}

/// Infix operators.
enum InfixOperator {
    Add,                // a + b
    And,                // a AND b
    Divide,             // a / b
    Equal,              // a = b
    Exponentiate,       // a ^ b
    GreaterThan,        // a > b
    GreaterThanOrEqual, // a >= b
    LessThan,           // a < b
    LessThanOrEqual,    // a <= b
    Like,               // a LIKE b
    Multiply,           // a * b
    NotEqual,           // a != b
    Or,                 // a OR b
    Remainder,          // a % b
    Subtract,           // a - b
}

impl InfixOperator {
    /// The operator precedence.
    fn precedence(&self) -> Precedence {
        match self {
            InfixOperator::Or => 1,
            InfixOperator::And => 2,
            InfixOperator::Equal | InfixOperator::NotEqual | InfixOperator::LessThan | InfixOperator::LessThanOrEqual | InfixOperator::GreaterThan | InfixOperator::GreaterThanOrEqual | InfixOperator::Like => 3,
            InfixOperator::Add | InfixOperator::Subtract => 4,
            InfixOperator::Multiply | InfixOperator::Divide | InfixOperator::Remainder => 5,
            InfixOperator::Exponentiate => 6,
        }
    }

    /// The operator associativity.
    fn associativity(&self) -> Associativity {
        match self {
            InfixOperator::Exponentiate => Associativity::Right,
            _ => Associativity::Left,
        }
    }

    /// Builds an AST expression for the infix operator.
    fn into_expression(self, lhs: ast::Expression, rhs: ast::Expression) -> ast::Expression {
        let op = match self {
            InfixOperator::Add => ast::Operator::Add(Box::new(lhs), Box::new(rhs)),
            InfixOperator::And => ast::Operator::And(Box::new(lhs), Box::new(rhs)),
            InfixOperator::Divide => ast::Operator::Divide(Box::new(lhs), Box::new(rhs)),
            InfixOperator::Equal => ast::Operator::Equal(Box::new(lhs), Box::new(rhs)),
            InfixOperator::Exponentiate => ast::Operator::Exponentiate(Box::new(lhs), Box::new(rhs)),
            InfixOperator::GreaterThan => ast::Operator::GreaterThan(Box::new(lhs), Box::new(rhs)),
            InfixOperator::GreaterThanOrEqual => ast::Operator::GreaterThanOrEqual(Box::new(lhs), Box::new(rhs)),
            InfixOperator::LessThan => ast::Operator::LessThan(Box::new(lhs), Box::new(rhs)),
            InfixOperator::LessThanOrEqual => ast::Operator::LessThanOrEqual(Box::new(lhs), Box::new(rhs)),
            InfixOperator::Like => ast::Operator::Like(Box::new(lhs), Box::new(rhs)),
            InfixOperator::Multiply => ast::Operator::Multiply(Box::new(lhs), Box::new(rhs)),
            InfixOperator::NotEqual => ast::Operator::NotEqual(Box::new(lhs), Box::new(rhs)),
            InfixOperator::Or => ast::Operator::Or(Box::new(lhs), Box::new(rhs)),
            InfixOperator::Remainder => ast::Operator::Remainder(Box::new(lhs), Box::new(rhs)),
            InfixOperator::Subtract => ast::Operator::Subtract(Box::new(lhs), Box::new(rhs)),
        };
        ast::Expression::Operator(op)
    }
}

/// Postfix operators.
enum PostfixOperator {
    Factorial,           // a!
    Is(ast::Literal),    // a IS NULL | NAN
    IsNot(ast::Literal), // a IS NOT NULL | NAN
}

impl PostfixOperator {
    // The operator precedence.
    fn precedence(&self) -> Precedence {
        3 // Same as comparison operators
    }

    /// Builds an AST expression for the operator.
    fn into_expression(self, lhs: ast::Expression) -> ast::Expression {
        match self {
            PostfixOperator::Factorial => ast::Expression::Operator(ast::Operator::Factorial(Box::new(lhs))),
            PostfixOperator::Is(lit) => ast::Expression::Operator(ast::Operator::Is(Box::new(lhs), lit)),
            PostfixOperator::IsNot(lit) => {
                // IS NOT is converted to NOT (IS ...)
                ast::Expression::Operator(ast::Operator::Not(Box::new(ast::Expression::Operator(ast::Operator::Is(Box::new(lhs), lit)))))
            }
        }
    }
}
